INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl gibt dem Benutzer "user1" Lesezugriff auf die Tabelle "employees"?', 2, '[{"text": "GRANT SELECT ON employees TO user1", "correct": true, "because": "Vergibt Leseberechtigung"}, {"text": "REVOKE SELECT ON employees FROM user1", "correct": false, "because": "Entzieht Rechte"}, {"text": "ALTER TABLE employees ADD user1", "correct": false, "because": "Kein DCL"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie entziehe ich "user2" das Recht, Daten in "orders" zu ändern?', 3, '[{"text": "REVOKE UPDATE ON orders FROM user2", "correct": true, "because": "Entzieht Änderungsrechte"}, {"text": "GRANT UPDATE ON orders TO user2", "correct": false, "because": "Gibt Rechte"}, {"text": "DENY UPDATE ON orders TO user2", "correct": false, "because": "Systemabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl erlaubt "user3" das Einfügen und Löschen in "customers"?', 4, '[{"text": "GRANT INSERT, DELETE ON customers TO user3", "correct": true, "because": "Kombinierte Rechtevergabe"}, {"text": "REVOKE INSERT, DELETE FROM customers user3", "correct": false, "because": "Syntax falsch"}, {"text": "GRANT ALL ON customers TO user3", "correct": false, "because": "Zu breit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert mit "GRANT SELECT ON products TO user4" bei Ausführung?', 2, '[{"text": "user4 kann products abfragen", "correct": true, "because": "Lesezugriff gewährt"}, {"text": "user4 kann products ändern", "correct": false, "because": "Nur SELECT erlaubt"}, {"text": "products wird gelöscht", "correct": false, "because": "Kein DDL"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl entzieht "user5" alle Rechte an "invoices"?', 3, '[{"text": "REVOKE ALL ON invoices FROM user5", "correct": true, "because": "Entzieht alle Rechte"}, {"text": "GRANT NONE ON invoices TO user5", "correct": false, "because": "Ungültige Syntax"}, {"text": "DROP USER user5", "correct": false, "because": "Kein DCL"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gebe ich "user6" die Berechtigung, die View "sales_report" zu lesen?', 2, '[{"text": "GRANT SELECT ON sales_report TO user6", "correct": true, "because": "Gilt auch für Views"}, {"text": "REVOKE SELECT ON sales_report FROM user6", "correct": false, "because": "Entzieht Rechte"}, {"text": "ALTER VIEW sales_report ADD user6", "correct": false, "because": "Kein DCL"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl erlaubt "role1" das Ändern von "inventory" mit Weitergabeoption?', 4, '[{"text": "GRANT UPDATE ON inventory TO role1 WITH GRANT OPTION", "correct": true, "because": "Erlaubt Weitergabe"}, {"text": "GRANT UPDATE ON inventory TO role1", "correct": false, "because": "Ohne Weitergabe"}, {"text": "REVOKE GRANT ON inventory FROM role1", "correct": false, "because": "Ungültig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was bewirkt "REVOKE INSERT ON orders FROM user7" nach "GRANT ALL ON orders TO user7"?', 3, '[{"text": "user7 kann alles außer INSERT", "correct": true, "because": "Nur INSERT entzogen"}, {"text": "user7 hat keine Rechte mehr", "correct": false, "because": "Nur INSERT betroffen"}, {"text": "orders wird gesperrt", "correct": false, "because": "Kein Lock"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl gibt "user8" Zugriff auf die Spalte "price" in "products"?', 5, '[{"text": "GRANT SELECT (price) ON products TO user8", "correct": true, "because": "Spaltenspezifisch"}, {"text": "GRANT SELECT ON products.price TO user8", "correct": false, "because": "Falsche Syntax"}, {"text": "REVOKE ALL ON products FROM user8", "correct": false, "because": "Entzieht Rechte"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie entziehe ich "user9" das Recht, "employees" zu löschen?', 2, '[{"text": "REVOKE DELETE ON employees FROM user9", "correct": true, "because": "Entzieht Löschrechte"}, {"text": "GRANT DELETE ON employees TO user9", "correct": false, "because": "Gibt Rechte"}, {"text": "DROP DELETE ON employees", "correct": false, "because": "Ungültig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl erlaubt "user10" das Ausführen einer Prozedur "calc_sales"?', 3, '[{"text": "GRANT EXECUTE ON calc_sales TO user10", "correct": true, "because": "Für Prozeduren"}, {"text": "GRANT SELECT ON calc_sales TO user10", "correct": false, "because": "Nur für Tabellen"}, {"text": "REVOKE EXECUTE FROM user10", "correct": false, "because": "Falsche Syntax"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert mit "GRANT ALL ON customers TO user11 WITH GRANT OPTION"?', 4, '[{"text": "user11 kann alle Rechte weitergeben", "correct": true, "because": "WITH GRANT OPTION erlaubt das"}, {"text": "user11 hat nur Lesezugriff", "correct": false, "because": "ALL umfasst mehr"}, {"text": "customers wird gesperrt", "correct": false, "because": "Kein Lock"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl entzieht "user12" das Recht, Daten in "orders" einzufügen?', 2, '[{"text": "REVOKE INSERT ON orders FROM user12", "correct": true, "because": "Entzieht Einfügerechte"}, {"text": "GRANT INSERT ON orders TO user12", "correct": false, "because": "Gibt Rechte"}, {"text": "ALTER TABLE orders DROP user12", "correct": false, "because": "Kein DCL"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gebe ich "user13" Zugriff auf die Tabelle "departments" für SELECT und UPDATE?', 3, '[{"text": "GRANT SELECT, UPDATE ON departments TO user13", "correct": true, "because": "Kombinierte Rechte"}, {"text": "REVOKE SELECT, UPDATE ON departments FROM user13", "correct": false, "because": "Entzieht Rechte"}, {"text": "GRANT ALL ON departments FROM user13", "correct": false, "because": "Falsche Syntax"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl erlaubt "role2" das Ändern von "invoices" ohne Weitergabe?', 4, '[{"text": "GRANT UPDATE ON invoices TO role2", "correct": true, "because": "Keine Weitergabeoption"}, {"text": "GRANT UPDATE ON invoices TO role2 WITH GRANT OPTION", "correct": false, "because": "Mit Weitergabe"}, {"text": "REVOKE UPDATE ON invoices FROM role2", "correct": false, "because": "Entzieht Rechte"}]'),
('00000000-0000-0000-0000-000000000000', 'Was bewirkt "REVOKE ALL ON products FROM user14" nach "GRANT SELECT, INSERT ON products TO user14"?', 3, '[{"text": "user14 verliert alle Rechte an products", "correct": true, "because": "ALL entzieht alles"}, {"text": "user14 behält SELECT", "correct": false, "because": "ALL umfasst alles"}, {"text": "products wird gelöscht", "correct": false, "because": "Kein DDL"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl gibt "user15" das Recht, die Funktion "get_total" auszuführen?', 2, '[{"text": "GRANT EXECUTE ON get_total TO user15", "correct": true, "because": "Für Funktionen"}, {"text": "GRANT SELECT ON get_total TO user15", "correct": false, "because": "Nur für Tabellen"}, {"text": "REVOKE EXECUTE ON get_total FROM user15", "correct": false, "because": "Entzieht Rechte"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie entziehe ich "user16" den Zugriff auf die Spalte "salary" in "employees"?', 5, '[{"text": "REVOKE SELECT (salary) ON employees FROM user16", "correct": true, "because": "Spaltenspezifisch"}, {"text": "REVOKE SELECT ON employees.salary FROM user16", "correct": false, "because": "Falsche Syntax"}, {"text": "GRANT SELECT ON employees TO user16", "correct": false, "because": "Gibt Rechte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl erlaubt "user17" das Lesen und Ändern von "orders" mit Weitergabe?', 4, '[{"text": "GRANT SELECT, UPDATE ON orders TO user17 WITH GRANT OPTION", "correct": true, "because": "Mit Weitergabe"}, {"text": "GRANT SELECT ON orders TO user17", "correct": false, "because": "Fehlt UPDATE"}, {"text": "REVOKE ALL ON orders FROM user17", "correct": false, "because": "Entzieht Rechte"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert mit "GRANT EXECUTE ON calc_profit TO user18" bei Ausführung?', 3, '[{"text": "user18 kann calc_profit ausführen", "correct": true, "because": "EXECUTE erlaubt das"}, {"text": "user18 kann calc_profit abfragen", "correct": false, "because": "SELECT fehlt"}, {"text": "calc_profit wird gelöscht", "correct": false, "because": "Kein DDL"}]');
